-- TASK-0065 Open Hand teaching items: ap-statistics (25 items). Generated by
-- scripts/content-seed/task0065_load/build_load_sql.py. Idempotent: re-running
-- skips content_keys already present in the target pack.
do $oht0065$
declare
  v_subject text := 'ap-statistics';
  v_tsv uuid := 'dae3c72e-82ca-4960-9552-1b034bd347e5';
  v_owner uuid := (select p.user_id from app.profiles p where p.user_id = 'f5a26c6b-3566-4d58-9e97-979fbb947564');
  v_items jsonb := $oht0065json$[{"content_key":"APSTATS-OHT-1.1","topic_code":"1.1","title":"Introducing Statistics: What Can We Learn from Data?","stem":"A free-response question describes a school that wants to know whether students who sleep more tend to earn higher quiz scores, and then supplies a table of sleep hours and quiz scores for 30 students. Which first move best reflects how statistics is used to answer a real question?","choices":[{"choice_key":"A","choice_text":"Begin computing the mean and standard deviation of both variables right away, since the table already holds everything needed.","is_correct":false,"rationale":"Tempting if you think statistics is just calculating numbers from a table — but numbers with no question behind them cannot be interpreted. Fix: name the question first, then choose calculations that help answer it."},{"choice_key":"B","choice_text":"Restate the investigative question in the context of sleep and quiz scores, and keep tying each calculation back to that question.","is_correct":true,"rationale":"This earns the point because every statistical tool is a way to answer the real-world question despite variability in the data. Opening with the question keeps later numbers connected to what the school actually wants to learn."},{"choice_key":"C","choice_text":"Ignore the school setting, because context is only decoration and the numbers alone answer the question.","is_correct":false,"rationale":"Tempting because the context does not change any arithmetic — but later free-response answers are graded on connecting results back to the situation. Fix: treat the context as part of the answer, not decoration."},{"choice_key":"D","choice_text":"Decide which procedure to use from the sample size of 30, and read the question only after the calculations are done.","is_correct":false,"rationale":"Tempting because sample size matters for conditions — but the type of data and the question determine the method, not n alone. Fix: read the question first so the method and conclusion fit what is being asked."}]},{"content_key":"APSTATS-OHT-1.2","topic_code":"1.2","title":"Variables","stem":"A marketing team records the three-digit area code of each customer's phone number (for example 212, 415, 305) for 500 customers. How should the variable 'area code' be classified?","choices":[{"choice_key":"A","choice_text":"Quantitative discrete, because area codes are whole numbers, and whole-number values that can be counted are discrete.","is_correct":false,"rationale":"Tempting because the values look like counts — but they are identifiers, not amounts of anything. Fix: ask whether adding or averaging the values makes sense; if not, the variable is categorical."},{"choice_key":"B","choice_text":"Quantitative continuous, because area codes fall anywhere along a number line between 200 and 999 like measurements do.","is_correct":false,"rationale":"Tempting because numbers can be placed on a number line — but a code of 415 is not 'more' than 212 in any measurable sense. Fix: ask whether the number measures an amount; if it is a label, classify the variable as categorical."},{"choice_key":"C","choice_text":"Quantitative, because the codes are written as numbers and can be sorted from smallest to largest in a list.","is_correct":false,"rationale":"Tempting because sorting is possible with digits — but being sortable does not make a value a measurement. Fix: classify by what the value means, not by whether it looks like a number."},{"choice_key":"D","choice_text":"Categorical, because each code is a label that places a customer in a group, and arithmetic on the codes has no meaning.","is_correct":true,"rationale":"This earns the point because a variable is categorical when its values name groups, even if the labels are written with digits. Adding or averaging area codes would produce a number with no real-world meaning."}]},{"content_key":"APSTATS-OHT-1.3","topic_code":"1.3","title":"Tabular Representation and Summary Statistics for One Categorical Variable","stem":"A survey of 80 students records each student's favorite pet type: dog 32, cat 24, fish 16, other 8. What is the relative frequency of students who chose cat?","choices":[{"choice_key":"A","choice_text":"0.30","is_correct":true,"rationale":"This earns the point because a relative frequency divides a category's count by the total number of observations: 24/80 = 0.30. The relative frequencies for all categories then sum to 1."},{"choice_key":"B","choice_text":"0.75","is_correct":false,"rationale":"Tempting if you divide the cat count by the largest category (24/32) — but a proportion of the whole must use the grand total. Fix: divide by the total 80, not by another category's count."},{"choice_key":"C","choice_text":"6.00","is_correct":false,"rationale":"Tempting if you divide the count by the number of categories (24/4) — but that does not give a proportion and the results would not sum to 1. Fix: divide by the total number of students, 80."},{"choice_key":"D","choice_text":"0.43","is_correct":false,"rationale":"Tempting if you divide by only part of the table, such as dog plus cat (24/56) — but the denominator must include every category. Fix: use the full total of 80."}]},{"content_key":"APSTATS-OHT-1.4","topic_code":"1.4","title":"Graphical Representations for One Categorical Variable","stem":"Two bar charts show favorite music genre. For 200 freshmen, the vertical axis is in counts, and the pop bar has height 60. For 50 seniors, the vertical axis is in percent of seniors, and the pop bar has height 40. Which comparison is valid?","choices":[{"choice_key":"A","choice_text":"A larger share of freshmen prefer pop, because the freshman bar (60) is taller than the senior bar (40).","is_correct":false,"rationale":"Tempting because the bar heights look comparable — but one axis is counts and the other is percent. Fix: put both on the same scale before comparing heights."},{"choice_key":"B","choice_text":"The same share of each grade prefers pop, because both bars show the pop category.","is_correct":false,"rationale":"Tempting because both bars represent one genre — but the bars measure different things. Fix: compute 60/200 = 30% and compare it with 40%."},{"choice_key":"C","choice_text":"A larger share of seniors than freshmen prefer pop: 40% of seniors versus 30% of freshmen.","is_correct":true,"rationale":"This earns the point because the groups have different sizes, so each bar must be converted to the same scale. 60 of 200 freshmen is 30%, which is less than the 40% of seniors."},{"choice_key":"D","choice_text":"No comparison is possible, because the two grades have different numbers of students.","is_correct":false,"rationale":"Tempting because unequal group sizes seem to block a fair comparison — but converting counts to percents is exactly how unequal groups are compared. Fix: use relative frequencies."}]},{"content_key":"APSTATS-OHT-1.5","topic_code":"1.5","title":"Graphical Representations for One Quantitative Variable","stem":"A histogram of 25 exam scores has bins of width 20 starting at 50. The tallest bar covers scores from 70 up to but not including 90 and has a height of 11. A student claims that at least two students scored exactly 85. What can be concluded?","choices":[{"choice_key":"A","choice_text":"The claim is confirmed, because the tall bar shows that many students earned exactly the same score within that bin.","is_correct":false,"rationale":"Tempting because tall bars look like frequent values — but a bar's height counts every score in the bin, and those 11 scores could all be different values from 70 to 89. Fix: read a bar's height as the count for its whole interval, not for one exact score."},{"choice_key":"B","choice_text":"The claim is false, because the histogram shows that the 11 scores in the tallest bar are spread across the whole interval.","is_correct":false,"rationale":"Tempting because the bar covers a wide interval — but the picture does not reveal how the 11 scores are distributed inside it. Fix: do not infer exact values from a binned graph."},{"choice_key":"C","choice_text":"The histogram cannot confirm or refute the claim, because it shows only how many scores fall in 70 to 89; a dotplot or stemplot of the same data would show each value.","is_correct":true,"rationale":"This earns the point because a histogram groups values into bins and hides the individual values inside them. A dotplot or stemplot keeps every data value, so it could settle the claim."},{"choice_key":"D","choice_text":"The claim can be checked only by redrawing the data as a bar chart, which shows each exact score.","is_correct":false,"rationale":"Tempting because bar charts also have bars — but bar charts display categorical variables, and scores are quantitative. Fix: use a dotplot or stemplot to see individual quantitative values."}]},{"content_key":"APSTATS-OHT-1.8","topic_code":"1.8","title":"Graphical Representations of Summary Statistics for One Quantitative Variable","stem":"An ordered data set of 11 values is 12, 38, 41, 44, 47, 50, 53, 56, 60, 67, 90, with Q1 = 41 and Q3 = 60. Using the 1.5 × IQR rule for outliers, where does the upper whisker of the boxplot end?","choices":[{"choice_key":"A","choice_text":"67","is_correct":true,"rationale":"This earns the point because the upper fence is 60 + 1.5(19) = 88.5, so 90 is an outlier and is plotted as a separate point. The whisker stops at the largest value that is not an outlier, 67."},{"choice_key":"B","choice_text":"90","is_correct":false,"rationale":"Tempting because whiskers often run to the maximum — but 90 is above the upper fence of 88.5, so it is an outlier. Fix: draw the whisker to the largest non-outlier and plot outliers separately."},{"choice_key":"C","choice_text":"88.5","is_correct":false,"rationale":"Tempting because 88.5 is the fence you just computed — but the fence is a cutoff, not a data value. Fix: end the whisker at the largest actual data value inside the fence, not at the fence itself."},{"choice_key":"D","choice_text":"60","is_correct":false,"rationale":"Tempting because the box ends at Q3 — but the whisker continues beyond the box to the largest non-outlier. Fix: compute the upper fence, Q3 + 1.5 × IQR, then extend the whisker past Q3 to the largest value inside it."}]},{"content_key":"APSTATS-OHT-1.9","topic_code":"1.9","title":"Comparisons of the Distributions for One Quantitative Variable","stem":"Maya scored 78 on a test with mean 70 and standard deviation 4. Jon scored 84 on a different test with mean 75 and standard deviation 9. Who performed better relative to the classmates who took the same test?","choices":[{"choice_key":"A","choice_text":"Jon, because his raw score of 84 is higher than 78.","is_correct":false,"rationale":"Tempting because 84 is the bigger number — but the tests have different means and spreads. Fix: convert each score to a z-score before comparing."},{"choice_key":"B","choice_text":"Jon, because he is 9 points above his mean while Maya is only 8 above hers.","is_correct":false,"rationale":"Tempting because 9 is more than 8 — but a point of distance means different things when the SDs differ (9 versus 4). Fix: divide the distance by the SD."},{"choice_key":"C","choice_text":"Neither, because scores from different tests can be compared only if the tests have the same mean.","is_correct":false,"rationale":"Tempting because different tests seem incomparable — but z-scores put both on a common scale. Fix: standardize, then compare."},{"choice_key":"D","choice_text":"Maya, because her z-score of 2.0 is higher than Jon's z-score of 1.0.","is_correct":true,"rationale":"This earns the point because z = (x − mean)/SD measures how many standard deviations a score is above its own mean. Maya's 2.0 beats Jon's 1.0, so she stands out more among her own test takers."}]},{"content_key":"APSTATS-OHT-1.10","topic_code":"1.10","title":"The Investigative Question Revisited and Data Collection","stem":"Researchers follow 500 adults for ten years. Each person reports weekly coffee consumption, and researchers record blood pressure each year. Nobody is told how much coffee to drink. Which statement best describes this study?","choices":[{"choice_key":"A","choice_text":"It is an experiment, because the same people were measured repeatedly over ten years.","is_correct":false,"rationale":"Tempting because tracking over time feels like active research — but measuring is not the same as imposing a treatment. Fix: ask whether researchers assigned the explanatory variable."},{"choice_key":"B","choice_text":"It is a prospective observational study, because researchers followed people forward in time without assigning any treatment.","is_correct":true,"rationale":"This earns the point because an experiment requires researchers to impose a treatment, and here people chose their own coffee habits. Following subjects forward and recording data makes it prospective observational, so it cannot support a cause-and-effect conclusion."},{"choice_key":"C","choice_text":"It is a retrospective observational study, because the researchers are looking at coffee habits and blood pressure of adults.","is_correct":false,"rationale":"Tempting because it is observational — but retrospective studies examine past records, while this one collects data going forward. Fix: check whether data are collected going forward or looked up from the past before you call a study retrospective."},{"choice_key":"D","choice_text":"It is an experiment, because the researchers measured blood pressure themselves.","is_correct":false,"rationale":"Tempting because researchers took the measurements — but experiments are defined by assigned treatments, not by who records the data. Fix: look for random assignment of a treatment."}]},{"content_key":"APSTATS-OHT-2.1","topic_code":"2.1","title":"Tabular and Graphical Representations for the Distributions of Two Categorical Variables","stem":"A segmented bar chart shows, for each of two clubs, the percent of members who prefer online meetings: 40% of Chess Club members and 75% of Art Club members. Which statement can be made from the chart alone?","choices":[{"choice_key":"A","choice_text":"More Art Club members than Chess Club members prefer online meetings.","is_correct":false,"rationale":"Tempting because 75% looks bigger than 40% — but the chart hides the club sizes, so counts cannot be compared. Fix: compare percents as percents, and find each group's total before you compare counts."},{"choice_key":"B","choice_text":"The two clubs have the same number of members, because each bar is the same total height.","is_correct":false,"rationale":"Tempting because every bar reaches 100% — but each bar is scaled to its own group. Fix: read each bar as 100% of its own group, and look for the group counts before you compare sizes."},{"choice_key":"C","choice_text":"Art Club has more members than Chess Club, because a larger share prefers online meetings.","is_correct":false,"rationale":"Tempting because a bigger percentage seems to mean a bigger group — but a percentage tells only what share, not how many. Fix: use a table or side-by-side counts for group sizes."},{"choice_key":"D","choice_text":"A greater proportion of Art Club members than Chess Club members prefer online meetings.","is_correct":true,"rationale":"This earns the point because a segmented bar chart shows each group's own percentages, so proportions can be compared across groups. 75% is greater than 40%."}]},{"content_key":"APSTATS-OHT-2.2","topic_code":"2.2","title":"Summary Statistics for Two Categorical Variables","stem":"A school asks 200 students whether they favor an earlier start time. Among 80 juniors, 20 say yes and 60 say no. Among 120 seniors, 60 say yes and 60 say no. Among seniors, what proportion favor the earlier start?","choices":[{"choice_key":"A","choice_text":"0.50","is_correct":true,"rationale":"This earns the point because a conditional relative frequency divides by the total of the group named in the question: 60/120 = 0.50. Conditioning on seniors makes 120 the denominator."},{"choice_key":"B","choice_text":"0.30","is_correct":false,"rationale":"Tempting if you divide by the grand total (60/200) — but that is a joint relative frequency, not the proportion within seniors. Fix: divide by the number of seniors."},{"choice_key":"C","choice_text":"0.75","is_correct":false,"rationale":"Tempting if you divide by the number of yes responses (60/80) — but that gives the share of yes responses who are seniors, the reverse of what was asked. Fix: the group in the condition supplies the denominator."},{"choice_key":"D","choice_text":"0.40","is_correct":false,"rationale":"Tempting if you use the overall proportion saying yes (80/200) — but that is a marginal relative frequency for all students. Fix: restrict to the seniors' row."}]},{"content_key":"APSTATS-OHT-2.4","topic_code":"2.4","title":"Introduction to Probability","stem":"A bag holds 5 red, 3 blue, and 4 green marbles, and one marble is drawn at random. What is the probability that it is red?","choices":[{"choice_key":"A","choice_text":"5/7, about 0.71","is_correct":false,"rationale":"Tempting if you compare red marbles with the non-red ones (5 to 7) — but probability divides by all outcomes, not just the others. Fix: put the total number of marbles, 12, in the denominator."},{"choice_key":"B","choice_text":"5/3, about 1.67","is_correct":false,"rationale":"Tempting if you compare red marbles with blue ones — but a probability can never exceed 1. Fix: check that every probability is between 0 and 1, and divide by the total number of marbles."},{"choice_key":"C","choice_text":"5/12, about 0.42","is_correct":true,"rationale":"This earns the point because with equally likely outcomes, probability is favorable outcomes over total outcomes: 5 red out of 12 marbles. The answer must lie between 0 and 1."},{"choice_key":"D","choice_text":"1/3, about 0.33","is_correct":false,"rationale":"Tempting if you treat the three colors as equally likely — but the colors have different counts, so the outcomes are not equally likely by color. Fix: count marbles, not colors."}]},{"content_key":"APSTATS-OHT-2.5","topic_code":"2.5","title":"Mutually Exclusive Events","stem":"A fair six-sided die is rolled once. Let A be the event that the roll is even, and B the event that the roll is greater than 4. What is P(A or B)?","choices":[{"choice_key":"A","choice_text":"4/6","is_correct":true,"rationale":"This earns the point because the events share the outcome 6, so they are not mutually exclusive. P(A or B) = 3/6 + 2/6 − 1/6 = 4/6, which matches counting the outcomes 2, 4, 5, 6."},{"choice_key":"B","choice_text":"5/6","is_correct":false,"rationale":"Tempting if you simply add 3/6 and 2/6 — but that double-counts the roll 6. Fix: subtract P(A and B) unless the events are mutually exclusive."},{"choice_key":"C","choice_text":"1/6","is_correct":false,"rationale":"Tempting if you multiply P(A) and P(B) — but a product is not the probability of 'or' and the events are not shown to be independent in that way. Fix: use the addition rule for 'or'."},{"choice_key":"D","choice_text":"1","is_correct":false,"rationale":"Tempting if you add all three of 3/6, 2/6, and 1/6 — but the overlap is subtracted, not added. Fix: P(A or B) = P(A) + P(B) − P(A and B)."}]},{"content_key":"APSTATS-OHT-2.8","topic_code":"2.8","title":"Introduction to Random Variables and Probability Distributions","stem":"The random variable X is the number of late arrivals in a day. The distribution is P(X=0) = 0.15, P(X=1) = 0.30, P(X=3) = 0.20, and P(X=4) = 0.10. The probability for X = 2 is not listed. What is P(X < 3)?","choices":[{"choice_key":"A","choice_text":"0.90","is_correct":false,"rationale":"Tempting if you include the boundary value 3 — but P(X < 3) excludes X = 3 and that would be P(X ≤ 3). Fix: decide whether the endpoint belongs before adding."},{"choice_key":"B","choice_text":"0.45","is_correct":false,"rationale":"Tempting if you add only the probabilities that are listed (0.15 + 0.30) — but P(X=2) is missing and belongs in the total. Fix: recover it by subtracting the known probabilities from 1."},{"choice_key":"C","choice_text":"0.80","is_correct":false,"rationale":"Tempting if you compute 1 − P(X=3) — but that includes X = 4, which is not below 3. Fix: add only the values 0, 1, and 2."},{"choice_key":"D","choice_text":"0.70","is_correct":true,"rationale":"This earns the point because probabilities sum to 1, so P(X=2) = 1 − 0.75 = 0.25. Then P(X < 3) = 0.15 + 0.30 + 0.25 = 0.70, which excludes X = 3."}]},{"content_key":"APSTATS-OHT-2.11","topic_code":"2.11","title":"The Normal Distribution","stem":"SAT-style scores in a large population are approximately normal with mean 500 and standard deviation 100. Approximately what percent of scores are above 700?","choices":[{"choice_key":"A","choice_text":"5%","is_correct":false,"rationale":"Tempting because 5% is the area outside 2 SD — but that counts both tails. Fix: split the outside area in half for one tail."},{"choice_key":"B","choice_text":"2.5%","is_correct":true,"rationale":"This earns the point because 700 is 2 standard deviations above the mean, and the empirical rule says 95% fall within 2 SD. The remaining 5% splits evenly between the two tails, leaving 2.5% above 700."},{"choice_key":"C","choice_text":"95%","is_correct":false,"rationale":"Tempting because 95% is the empirical-rule number for 2 SD — but that is the area between 300 and 700. Fix: shade the region the question asks about (above 700) before you read off a percent."},{"choice_key":"D","choice_text":"16%","is_correct":false,"rationale":"Tempting if you use the 68% rule — but 700 is 2 SD, not 1 SD, above the mean. Fix: compute z = (700 − 500)/100 = 2 first."}]},{"content_key":"APSTATS-OHT-2.12","topic_code":"2.12","title":"Sampling Distributions and the Central Limit Theorem","stem":"A population is strongly right-skewed with mean 40 and standard deviation 24. Many random samples of size 64 are taken, the mean of each sample is computed, and the sample means are plotted. Which description of the plot is best?","choices":[{"choice_key":"A","choice_text":"Right-skewed like the population, centered near 40, with standard deviation about 3.","is_correct":false,"rationale":"Tempting because the population is skewed — but with n = 64 the sample means pile up symmetrically. Fix: for a large sample size, describe the distribution of sample means as approximately normal, whatever the population's shape."},{"choice_key":"B","choice_text":"Approximately normal, centered near 40, with standard deviation about 3.","is_correct":true,"rationale":"This earns the point because the sample size of 64 is large enough for the Central Limit Theorem, so the sampling distribution of the mean is approximately normal. Its center is 40 and its spread is 24/√64 = 3."},{"choice_key":"C","choice_text":"Approximately normal, centered near 40, with standard deviation about 24.","is_correct":false,"rationale":"Tempting because the population SD is 24 — but averages vary less than individual values. Fix: divide σ by √n."},{"choice_key":"D","choice_text":"Approximately normal, centered near 40, with standard deviation about 0.375.","is_correct":false,"rationale":"Tempting if you divide 24 by 64 — but the standard deviation of the mean uses √n, not n. Fix: divide σ by √n, not by n: 24/√64 = 3."}]},{"content_key":"APSTATS-OHT-3.1","topic_code":"3.1","title":"Estimators","stem":"The true proportion of voters who support a measure is p = 0.50. A pollster takes one random sample of 200 voters and gets a sample proportion of 0.44. Which statement is best?","choices":[{"choice_key":"A","choice_text":"The sample proportion is a biased estimator, because the result of 0.44 does not equal the true value of 0.50.","is_correct":false,"rationale":"Tempting because the estimate missed the target — but bias is about the long-run center, not one miss. Fix: judge bias by the mean of the sampling distribution."},{"choice_key":"B","choice_text":"The sampling method must be flawed, because a properly done random sample should give a result of exactly 0.50.","is_correct":false,"rationale":"Tempting because random sampling feels like it should reproduce the population — but random samples vary. Fix: expect sample-to-sample variability around p."},{"choice_key":"C","choice_text":"The sample proportion is biased low, and taking a larger random sample of 400 voters would remove that bias.","is_correct":false,"rationale":"Tempting because larger samples help — but larger n reduces variability, not bias, and a single 0.44 does not show bias. Fix: bias comes from the method, spread comes from n."},{"choice_key":"D","choice_text":"This is consistent with an unbiased estimator, because unbiased means the center of all possible sample proportions is p, not that every sample hits p.","is_correct":true,"rationale":"This earns the point because bias describes the sampling distribution over many samples. One sample falling 0.06 below p is ordinary sampling variability and says nothing against unbiasedness."}]},{"content_key":"APSTATS-OHT-3.3","topic_code":"3.3","title":"Constructing a Confidence Interval for a Population Proportion","stem":"A city planner wants to estimate the proportion of residents who support a new bus line with a 95% confidence interval and a margin of error of no more than 0.03. There is no earlier estimate of the proportion. What is the smallest sample size that guarantees this margin of error? (Use z* = 1.96.)","choices":[{"choice_key":"A","choice_text":"1068","is_correct":true,"rationale":"This earns the point because with no prior estimate you use p̂ = 0.5, the worst case. n ≥ 1.96²(0.5)(0.5)/0.03² ≈ 1067.1, and you round up to 1068 to keep the margin of error at or below 0.03."},{"choice_key":"B","choice_text":"1067","is_correct":false,"rationale":"Tempting because 1067.1 rounds to 1067 in ordinary rounding — but 1067 would give a margin of error slightly above 0.03. Fix: always round sample size up."},{"choice_key":"C","choice_text":"752","is_correct":false,"rationale":"Tempting if you use z* = 1.645 from a 90% interval — but the problem asks for 95% confidence, so z* = 1.96. Fix: match z* to the confidence level."},{"choice_key":"D","choice_text":"4269","is_correct":false,"rationale":"Tempting if you leave out the p̂(1 − p̂) factor and compute (1.96/0.03)² — but that factor equals 0.25 in the worst case. Fix: include 0.5 × 0.5 in the numerator."}]},{"content_key":"APSTATS-OHT-3.5","topic_code":"3.5","title":"Setting Up a Test for a Population Proportion","stem":"A bottling company claims that 22% of its bottles are underfilled. An inspector suspects the true proportion is different from 22%. In a random sample of 150 bottles, 40 are underfilled. Which pair of hypotheses should the inspector test?","choices":[{"choice_key":"A","choice_text":"H₀: p̂ = 0.22 versus Hₐ: p̂ ≠ 0.22, where p̂ is the proportion underfilled in the sample.","is_correct":false,"rationale":"Tempting because p̂ is the symbol attached to the sample — but hypotheses are about the fixed population parameter. Fix: write p, not p̂."},{"choice_key":"B","choice_text":"H₀: p = 0.22 versus Hₐ: p > 0.22, where p is the true proportion of underfilled bottles.","is_correct":false,"rationale":"Tempting if you notice the sample result is above 22% (40/150 ≈ 0.27) — but the direction must come from the research question, not the data. Fix: use ≠ in Hₐ whenever the claim is that the proportion is 'different from' a value."},{"choice_key":"C","choice_text":"H₀: p = 0.22 versus Hₐ: p ≠ 0.22, where p is the true proportion of all bottles that are underfilled.","is_correct":true,"rationale":"This earns the point because hypotheses describe the population proportion p, the null value comes from the claim, and 'different from' calls for a two-sided alternative."},{"choice_key":"D","choice_text":"H₀: p = 0.27 versus Hₐ: p ≠ 0.27, where p is the true proportion of underfilled bottles.","is_correct":false,"rationale":"Tempting if you put the sample proportion into the null — but the null value is the claimed 0.22, not the observed 0.27. Fix: write the hypotheses with the claimed value, 0.22, and save the sample result for the test statistic."}]},{"content_key":"APSTATS-OHT-3.7","topic_code":"3.7","title":"Carrying Out a Test for a Population Proportion","stem":"A company claims that 30% of customers renew. In a random sample of 150 customers, 60 renew (p̂ = 0.40). For a one-sample z-test of H₀: p = 0.30, what is the test statistic?","choices":[{"choice_key":"A","choice_text":"z ≈ 2.67","is_correct":true,"rationale":"This earns the point because the standard error under H₀ uses p₀: √(0.30 × 0.70/150) ≈ 0.0374. Then z = (0.40 − 0.30)/0.0374 ≈ 2.67."},{"choice_key":"B","choice_text":"z = 2.50","is_correct":false,"rationale":"Tempting if you put p̂ under the radical, giving √(0.40 × 0.60/150) = 0.04 — but a test assumes H₀ is true. Fix: use p₀ in the standard error."},{"choice_key":"C","choice_text":"z ≈ 0.22","is_correct":false,"rationale":"Tempting if you forget to divide the variance by n — but the standard error must include n. Fix: √(p₀(1 − p₀)/n), not √(p₀(1 − p₀))."},{"choice_key":"D","choice_text":"z ≈ 71.4","is_correct":false,"rationale":"Tempting if you divide by p₀(1 − p₀)/n and forget the square root — but that is a variance, not a standard error. Fix: take the square root."}]},{"content_key":"APSTATS-OHT-3.9","topic_code":"3.9","title":"Sampling Distributions for the Difference Between Sample Proportions","stem":"In population 1, p₁ = 0.60, and in population 2, p₂ = 0.50. Independent random samples of sizes n₁ = 100 and n₂ = 150 are taken. What is the standard deviation of the sampling distribution of p̂₁ − p̂₂?","choices":[{"choice_key":"A","choice_text":"0.0271","is_correct":false,"rationale":"Tempting because the statistic is a difference — but variances add even when the statistics are subtracted. Fix: use a plus sign inside the square root."},{"choice_key":"B","choice_text":"0.0898","is_correct":false,"rationale":"Tempting if you add the two separate standard deviations (0.0490 + 0.0408) — but standard deviations do not add; variances do. Fix: add the variances, then take one square root."},{"choice_key":"C","choice_text":"0.0041","is_correct":false,"rationale":"Tempting if you stop at the sum of the two variances — but that value is the variance. Fix: take the square root to get the standard deviation."},{"choice_key":"D","choice_text":"0.0638","is_correct":true,"rationale":"This earns the point because independent variances add: √(0.60(0.40)/100 + 0.50(0.50)/150) = √0.004067 ≈ 0.0638."}]},{"content_key":"APSTATS-OHT-3.10","topic_code":"3.10","title":"Constructing a Confidence Interval for the Difference Between Two Population Proportions","stem":"In a random sample of 100 customers using app A, 80 are satisfied. In an independent random sample of 100 customers using app B, 50 are satisfied. Which is the 95% confidence interval for p_A − p_B?","choices":[{"choice_key":"A","choice_text":"(0.168, 0.432)","is_correct":false,"rationale":"Tempting if you pool the two samples into one proportion of 0.65 — but pooling assumes p_A = p_B, which an interval does not assume. Fix: keep each sample's own p̂ in the standard error."},{"choice_key":"B","choice_text":"(0.174, 0.426)","is_correct":true,"rationale":"This earns the point because the interval uses each sample's own proportion: SE = √(0.8(0.2)/100 + 0.5(0.5)/100) ≈ 0.0640, so 0.30 ± 1.96(0.0640) gives about (0.174, 0.426)."},{"choice_key":"C","choice_text":"(0.195, 0.405)","is_correct":false,"rationale":"Tempting if you use z* = 1.645 — but that critical value belongs to 90% confidence. Fix: use 1.96 for 95%."},{"choice_key":"D","choice_text":"(0.292, 0.308)","is_correct":false,"rationale":"Tempting if you skip the square root and multiply 1.96 by 0.0041 — but that is a variance, not a standard error. Fix: take the square root before multiplying by z*."}]},{"content_key":"APSTATS-OHT-3.11","topic_code":"3.11","title":"Justifying a Claim Based on a Confidence Interval for the Difference Between Two Population Proportions","stem":"A 95% confidence interval for p₁ − p₂, the difference in renewal rates between new app users and old app users, is (−0.02, 0.14). Which conclusion is best supported?","choices":[{"choice_key":"A","choice_text":"There is convincing evidence that p₁ is greater than p₂, because most of the interval is positive.","is_correct":false,"rationale":"Tempting because the interval leans positive — but any interval containing 0 allows equal proportions. Fix: check whether 0 is inside, not which side has more area."},{"choice_key":"B","choice_text":"There is not convincing evidence of a difference in renewal rates, because 0 is a plausible value for p₁ − p₂.","is_correct":true,"rationale":"This earns the point because an interval that contains 0 leaves 'no difference' plausible. The decision depends on whether 0 is inside the interval, not on how much of the interval is positive."},{"choice_key":"C","choice_text":"There is convincing evidence that the two proportions are equal, because 0 is in the interval.","is_correct":false,"rationale":"Tempting because 0 is a plausible value — but plausible does not mean proven. Fix: say 'not convincing evidence of a difference', never that the proportions are equal."},{"choice_key":"D","choice_text":"There is a 95% chance that p₁ − p₂ is between −0.02 and 0.14.","is_correct":false,"rationale":"Tempting because the interval has a 95% label — but the parameter is fixed, so the 95% describes the method. Fix: say 'we are 95% confident' and then use the interval to answer the claim."}]},{"content_key":"APSTATS-OHT-3.12","topic_code":"3.12","title":"Setting Up a Test for the Difference Between Two Population Proportions","stem":"Sample 1 has n₁ = 80 and 48 successes; sample 2 has n₂ = 120 and 60 successes. For a test of H₀: p₁ = p₂, which value of the combined proportion p̂_c belongs in the standard error?","choices":[{"choice_key":"A","choice_text":"0.55","is_correct":false,"rationale":"Tempting if you average 0.60 and 0.50 — but the samples have different sizes, so each should count in proportion to n. Fix: total successes divided by total sample size."},{"choice_key":"B","choice_text":"0.60","is_correct":false,"rationale":"Tempting if you use only sample 1's proportion — but the pooled estimate uses both samples. Fix: combine the successes and the sample sizes."},{"choice_key":"C","choice_text":"0.10","is_correct":false,"rationale":"Tempting if you use the difference p̂₁ − p̂₂ — but that is the numerator of the test statistic, not the common proportion. Fix: pooled p̂ comes from adding counts."},{"choice_key":"D","choice_text":"0.54","is_correct":true,"rationale":"This earns the point because under H₀ both samples share one proportion, estimated by combining all successes over all observations: (48 + 60)/(80 + 120) = 108/200 = 0.54."}]},{"content_key":"APSTATS-OHT-3.13","topic_code":"3.13","title":"Carrying Out a Test for the Difference Between Two Population Proportions","stem":"A random sample of 60 teens includes 45 who own a smartwatch (p̂₁ = 0.75). An independent random sample of 140 adults includes 70 who own one (p̂₂ = 0.50). For H₀: p₁ = p₂ versus Hₐ: p₁ > p₂, what is the test statistic?","choices":[{"choice_key":"A","choice_text":"z ≈ 3.28","is_correct":true,"rationale":"This earns the point because a test uses the pooled proportion p̂_c = 115/200 = 0.575. SE = √(0.575(0.425)(1/60 + 1/140)) ≈ 0.0763, so z = 0.25/0.0763 ≈ 3.28."},{"choice_key":"B","choice_text":"z ≈ 3.57","is_correct":false,"rationale":"Tempting if you reuse the confidence interval's standard error with each sample's own p̂ — but a test assumes p₁ = p₂. Fix: pool the samples under H₀."},{"choice_key":"C","choice_text":"z ≈ 7.15","is_correct":false,"rationale":"Tempting if you pool but use 1/(n₁ + n₂) in place of 1/n₁ + 1/n₂ — but each sample contributes its own sample size. Fix: use (1/n₁ + 1/n₂)."},{"choice_key":"D","choice_text":"z ≈ −3.28","is_correct":false,"rationale":"Tempting if you subtract in the wrong order — but Hₐ: p₁ > p₂ is supported by a positive difference p̂₁ − p̂₂. Fix: subtract in the same order as the hypotheses."}]},{"content_key":"APSTATS-OHT-3.15","topic_code":"3.15","title":"Carrying Out a Chi-Square Test for Homogeneity or Independence","stem":"A random sample of 100 people is classified by two categorical variables. The observed counts are: row 1 has 30 and 20; row 2 has 10 and 40. The expected counts are 20 and 30 in row 1, and 20 and 30 in row 2. What is the chi-square test statistic?","choices":[{"choice_key":"A","choice_text":"20.83","is_correct":false,"rationale":"Tempting if you divide by the observed counts — but the denominator is the expected count. Fix: divide each squared difference by E."},{"choice_key":"B","choice_text":"400","is_correct":false,"rationale":"Tempting if you add the squared differences and stop — but each must be scaled by its expected count. Fix: divide each (O − E)² by E before summing."},{"choice_key":"C","choice_text":"16.67","is_correct":true,"rationale":"This earns the point because χ² sums (observed − expected)²/expected over every cell: 100/20 + 100/30 + 100/20 + 100/30 ≈ 16.67."},{"choice_key":"D","choice_text":"1.67","is_correct":false,"rationale":"Tempting if you use the size of each gap, |O − E|, without squaring it: 10/20 + 10/30 + 10/20 + 10/30 ≈ 1.67. But the statistic squares each difference first. Fix: use (O − E)²/E for every cell."}]}]$oht0065json$::jsonb;
  v_pv uuid; v_npv int;
  r jsonb; c jsonb;
  v_ci uuid; v_civ uuid; v_key text; v_correct text;
  v_loaded int := 0; v_skipped int := 0; v_released int := 0;
begin
  select count(*) into v_npv
  from app.exam_pack_versions epv join app.exam_packs ep on ep.id = epv.exam_pack_id
  join app.subjects s on s.id = ep.subject_id
  where s.subject_key = v_subject and epv.status = 'published' and epv.retired_at is null;
  if v_npv = 0 then
    raise exception 'task0065: no published, non-retired exam pack version for %', v_subject;
  end if;
  -- Prefer the published pack that already holds teaching items (two exist for
  -- Statistics in Development); otherwise require exactly one.
  select epv.id into v_pv
  from app.exam_pack_versions epv join app.exam_packs ep on ep.id = epv.exam_pack_id
  join app.subjects s on s.id = ep.subject_id
  where s.subject_key = v_subject and epv.status = 'published' and epv.retired_at is null
    and (v_npv = 1 or exists (select 1 from app.open_hand_teaching_items t
                              join app.content_items ci on ci.id = t.content_item_id
                              where ci.exam_pack_version_id = epv.id))
  order by (select count(*) from app.open_hand_teaching_items t join app.content_items ci on ci.id = t.content_item_id
            where ci.exam_pack_version_id = epv.id) desc, epv.id
  limit 1;
  if v_pv is null then
    raise exception 'task0065: % has % published packs and none holds teaching items; pick one explicitly', v_subject, v_npv;
  end if;

  for r in select * from jsonb_array_elements(v_items) loop
    v_key := r->>'content_key';
    if exists (select 1 from app.content_items where exam_pack_version_id = v_pv and content_key = v_key) then
      v_skipped := v_skipped + 1;
      continue;
    end if;
    if jsonb_array_length(r->'choices') <> 4
       or (select count(*) from jsonb_array_elements(r->'choices') x where (x->>'is_correct')::boolean) <> 1 then
      raise exception 'task0065: % must have 4 choices with exactly one correct', v_key;
    end if;
    if not exists (select 1 from app.taxonomy_topics tt where tt.taxonomy_source_version = v_tsv
                   and tt.topic_code = r->>'topic_code') then
      raise exception 'task0065: topic % not in taxonomy %', r->>'topic_code', v_tsv;
    end if;
    select x->>'choice_key' into v_correct from jsonb_array_elements(r->'choices') x
    where (x->>'is_correct')::boolean;

    insert into app.content_items (exam_pack_version_id, content_key, item_type, title, status)
    values (v_pv, v_key, 'mcq', r->>'title', 'draft')
    returning id into v_ci;

    insert into app.content_item_versions (content_item_id, version_num, stem, content_hash, status,
      review_status, rubric_type, evaluator_strategy, canonical_answer_1)
    values (v_ci, 1, r->>'stem', md5(v_key), 'draft', 'tutor_review_pending', 'mcq', 'rule_based_mcq', v_correct)
    returning id into v_civ;

    for c in select * from jsonb_array_elements(r->'choices') loop
      insert into app.mcq_choices (content_item_version_id, choice_key, choice_text, is_correct, rationale)
      values (v_civ, c->>'choice_key', c->>'choice_text', (c->>'is_correct')::boolean, c->>'rationale');
    end loop;

    insert into app.content_item_cells (content_item_version_id, content_item_id, taxonomy_source_version,
      topic_code, skill_code, is_primary, assignment_status, source, model_run_id)
    values (v_civ, v_ci, v_tsv, r->>'topic_code', null, true, 'authored', 'task0065_oht_generated_2026_10_06',
      'TASK-0065 Open Hand teaching batch 2026-10-06 (authored to this topic; checked per CHECK_RESULTS.md)');

    -- Publish gates: enforce_publish_gate (approved review_status),
    -- tg_content_pipeline_guard_publish (published only from reviewed_approved),
    -- enforce_mcq_stem_choice_sync (runs on publish; choices exist by now).
    update app.content_item_versions set status = 'reviewed_approved', review_status = 'question_review_approved',
      approved_by = v_owner, approved_at = now() where id = v_civ;
    update app.content_item_versions set status = 'published', published_at = now() where id = v_civ;
    update app.content_items set status = 'reviewed_approved' where id = v_ci;
    update app.content_items set status = 'published' where id = v_ci;

    insert into app.open_hand_teaching_items (content_item_id, topic_code, source, note)
    values (v_ci, r->>'topic_code', 'generated', 'TASK-0065 batch 2026-10-06')
    on conflict (content_item_id) do nothing;
    v_loaded := v_loaded + 1;
  end loop;

  -- Return superseded spares (same subject + topic) to scoring.
  with rel as (
    update app.open_hand_teaching_items t set released_at = now()
    from app.content_items ci, app.exam_pack_versions epv, app.exam_packs ep, app.subjects s
    where ci.id = t.content_item_id and epv.id = ci.exam_pack_version_id and ep.id = epv.exam_pack_id
      and s.id = ep.subject_id and s.subject_key = v_subject
      and t.source = 'spare' and t.released_at is null
      and exists (select 1 from app.open_hand_teaching_items g
                  join app.content_items gci on gci.id = g.content_item_id
                  where g.source = 'generated' and g.released_at is null and g.note = 'TASK-0065 batch 2026-10-06'
                    and g.topic_code = t.topic_code and gci.exam_pack_version_id = v_pv
                    and gci.status = 'published')
    returning t.content_item_id)
  select count(*) into v_released from rel;

  raise notice 'task0065 %: pack %, loaded %, skipped %, spares released %', v_subject, v_pv, v_loaded, v_skipped, v_released;
end
$oht0065$;
